-- Venue Live Guest "RUPS / AGM". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara rups), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'rups', 'RUPS / AGM (aula rapat korporat)', 'rups', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 114, 'center 38%',
  $t${"name":"RUPS","orn":"diamond","ui":{"ivory":"#FBF8F3","white":"#FFFFFF","soft":"#EDE4F5","soft2":"#CDB8E3","accent":"#5B2A86","deep":"#3A1A57","ink":"#241036","mute":"#7A6B8C","line":"#DDD0EA","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFCF8","ink":"#241036","accent":"#5B2A86","gold":"#C9A227","leaf":"#EDE4F5","hbg":"rgba(251,248,243,.94)","hline":"#CDB8E3","motif":"diamond"},"hud":{"bg":"rgba(58,26,87,.84)","acc":"#F2D98A","on":"#241036"},"scr":{"wine":"#3A1A57","veil":"251,248,243"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'rups');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/rups/speakers.webp","w":1.5},"rope":{"url":"/assets/live-decor/rups/rope.webp","w":2.2},"stall_snacks":{"url":"/assets/live-decor/rups/stall_snacks.webp","w":1.6},"stall_candy":{"url":"/assets/live-decor/rups/stall_candy.webp","w":1.5},"stall_drinks":{"url":"/assets/live-decor/rups/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/rups/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/rups/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/rups/arch.webp","w":12,"x":0,"z":-27},"fountain":{"url":"/assets/live-decor/rups/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/rups/sign.webp","w":1.2},"easel":{"url":"/assets/live-decor/rups/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/rups/table.webp"},"banner":{"url":"/assets/live-decor/rups/banner.webp","w":1.3},"gifts":{"url":"/assets/live-decor/rups/gifts.webp","w":1.4},"planter":{"url":"/assets/live-decor/rups/planter.webp","w":1.3},"av_host":{"url":"/assets/live-decor/rups/av_host.webp","name":"Direktur Jas Ungu"},"av_l1":{"url":"/assets/live-decor/rups/av_l1.webp","name":"Direktur Jas Ungu"},"av_l2":{"url":"/assets/live-decor/rups/av_l2.webp","name":"Komisaris Jas Abu"},"av_l3":{"url":"/assets/live-decor/rups/av_l3.webp","name":"Notaris Batik"},"av_l4":{"url":"/assets/live-decor/rups/av_l4.webp","name":"Pemegang Saham"},"av_p1":{"url":"/assets/live-decor/rups/av_p1.webp","name":"Komisaris Hijab"},"av_p2":{"url":"/assets/live-decor/rups/av_p2.webp","name":"Direktur Keuangan"},"av_p3":{"url":"/assets/live-decor/rups/av_p3.webp","name":"Sekretaris Kebaya"}}$d$::jsonb, background_url = '/assets/live-decor/rups/painting.webp', active = true, updated_at = now() where key = 'rups';
